import contextJson from "./context.json";
import type { ContextData, DataSource, MbnMeasure } from "@/lib/types";

// Outside figures that give budget numbers a scale: population, inflation, service volumes and
// MBNCanada measures. Generated by scripts/extract_context.py — never edit the JSON by hand.
// Server-only (~600KB). Every helper returns null rather than guessing when a year is missing.

// Via unknown: TS infers per-year object literals for the JSON that don't widen to Record<string, …>.
const CTX = contextJson as unknown as ContextData;

export const POPULATION_SOURCE = CTX.population.source;
export const CPI_SOURCE = CTX.cpi.source;
/** Latest year with a full-year CPI; inflation-adjusted figures are in this year's dollars. */
export const CPI_BASE_YEAR = Math.max(...Object.keys(CTX.cpi.values).map(Number));
export const LATEST_POPULATION_YEAR = Math.max(...Object.keys(CTX.population.values).map(Number));

export function population(year: number): number | null {
  return CTX.population.values[String(year)] ?? null;
}

export function perResident(amount: number, year: number): number | null {
  const p = population(year);
  return p ? amount / p : null;
}

/** `amount` (in `year` dollars) expressed in CPI_BASE_YEAR dollars. */
export function inBaseYearDollars(amount: number, year: number): number | null {
  const cpi = CTX.cpi.values[String(year)], base = CTX.cpi.values[String(CPI_BASE_YEAR)];
  return cpi && base ? amount * (base / cpi) : null;
}

export interface UnitCost {
  id: string;
  year: number;
  cost: number;
  volume: number;
  unit: string;
  volumeLabel: string;
  caveat: string;
  volumeSource: DataSource;
}

/** Program spending ÷ its service volume, for years where both exist. */
export function unitCost(programName: string, year: number, expenses: number): UnitCost | null {
  const def = CTX.unitCosts.find(u => u.programs.includes(programName));
  const v = def?.volumes[String(year)];
  if (!def || !v || !expenses) return null;
  return {
    id: def.id, year, cost: expenses / v.value, volume: v.value, unit: def.unit, volumeLabel: def.volumeLabel, caveat: def.caveat,
    volumeSource: {
      publisher: def.publisher, dataset: def.dataset, datasetUrl: def.datasetUrl, fileUrl: v.fileUrl, member: null,
      locator: v.locator, method: `Count of ${def.volumeLabel} in ${year}.`,
    },
  };
}

export interface MbnBlock {
  area: string;
  year: number;
  /** True when the budget year itself has MBNCanada data; false means the nearest year is shown. */
  exactYear: boolean;
  measures: MbnMeasure[];
  dataset: string;
  datasetUrl: string;
  publisher: string;
}

/** MBNCanada measures for areas paired with this program, for the budget year or the nearest year with data. */
export function mbnFor(programName: string, year: number): MbnBlock[] {
  return Object.entries(CTX.mbn.areas)
    .filter(([, a]) => a.programs.includes(programName))
    .map(([area, a]) => {
      const years = Object.keys(a.years).map(Number);
      const pick = years.includes(year) ? year : years.reduce((best, y) => (Math.abs(y - year) < Math.abs(best - year) ? y : best), years[0]);
      return {
        area, year: pick, exactYear: pick === year, measures: a.years[String(pick)],
        dataset: CTX.mbn.dataset, datasetUrl: CTX.mbn.datasetUrl, publisher: CTX.mbn.publisher,
      };
    });
}

/** Formats an MBNCanada result: dollars only when the measure is a cost, % only when it says "Percent". */
export function fmtMbnResult(m: MbnMeasure): string {
  if (/^Percent\b/i.test(m.name)) return `${(m.result * 100).toFixed(1)}%`;
  if (/\bCost/i.test(m.name)) return `$${m.result.toLocaleString("en-CA", { maximumFractionDigits: m.result < 100 ? 2 : 0 })}`;
  return m.result.toLocaleString("en-CA", { maximumFractionDigits: 3 });
}
